#include <stdio.h>
#include <string.h>

int fun(char *str)
{
    int i, n = strlen(str);
    for (i = 0; i < n / 2; i++)
    {
        if (str[i] != str[n - 1 - i])
            return 0;
    }
    return 1;
}

int main()
{
    char s[101];
    scanf("%s", s);
    if (fun(s))
        printf("YES\n");
    else
        printf("NO\n");
    return 0;
}

#include <stdio.h>

void fun(int m, int a[], int *n)
{
    int i;
    *n = 0;
    for (i = 7; i <= m; i++)
    {
        if ((i % 7 == 0) || (i % 11 == 0))
            a[(*n)++] = i;
    }
}

int main()
{
    int m, a[1000], n, i;
    scanf("%d", &m);
    fun(m, a, &n);
    for (i = 0; i < n; i++)
    {
        if (i > 0) printf(" ");
        printf("%d", a[i]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <string.h>

void fun(char *s)
{
    int i;
    char *p = s;
    while (*p) p++;
    p--;
    while (p >= s && *p == '*') p--;
    *(p + 1) = '\0';
}

int main()
{
    char s[101];
    scanf("%s", s);
    fun(s);
    printf("%s\n", s);
    return 0;
}
